import networkx as nx
G = nx.Graph()
G.add_nodes_from(range(10))
G.add_edges_from([(0,7), (0,4), (0,2), (2,9), (1,4), (4,6), (2,8), (1,8), (3,9)])
while True:
    try:
        nx.find_cycle(G)
        break
    except nx.NetworkXNoCycle:
        for u in range(10):
            for v in range(u+1, 10):
                if not G.has_edge(u, v):
                    G.add_edge(u, v)
                    try:
                        nx.find_cycle(G)
                        G.remove_edge(u, v)
                    except nx.NetworkXNoCycle:
                        pass
print("SATISFIABLE")
print(list(G.edges))
